WITH products_by_supplier AS (SELECT supplier_id, MAX(launch_date) AS latest_launch_date, ROUND((100 * SUM(CASE WHEN category = 'Grocery' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_grocery FROM products GROUP BY supplier_id) SELECT s.city, s.rating, pbs.latest_launch_date, pbs.pct_grocery FROM suppliers s JOIN products_by_supplier pbs ON s.id = pbs.supplier_id WHERE pbs.pct_grocery > 24 ORDER BY 4;
